package CodeGeneratorQJS;

use File::stat;

my $module = "";
my $outputDir = "";

my @headerContent = ();
my @implContentHeader = ();
my @implContent = ();
my %implIncludes = ();

# Default .h template
my $headerTemplate = << "EOF";
/*
 * Copyright (c) 2026, Zhang Ji Peng <onecoolx\@gmail.com>
 * All rights reserved.
 *
