static String cssPropertyName(const char* name)
{
    if (!name || !name[0])
        return String();

    Vector<char> buf;
    for (int i = 0; name[i]; ++i) {
        char c = name[i];
        if (c >= 'A' && c <= 'Z') {
            buf.append('-');
            buf.append(c - 'A' + 'a');
        } else {
            buf.append(c);
        }
    }
    buf.append('\0');

    String prop(buf.data());
    if (prop.startsWith("webkit-") || prop.startsWith("khtml-"))
        prop = "-" + prop;
    return prop;
}

