/* webview.cpp - WatchWeb webview (Agave engine wrapper)
 *
 * Copyright (C) 2026 Zhang Ji Peng
 * Contact : onecoolx@gmail.com
 */

#include "config.h"
#include "lvgl.h"
#include "macross.h"

#include "webview.h"

WebView::WebView(lv_obj_t* parent)
    : m_view(nullptr)
    , m_canvas(nullptr)
    , m_parent(parent)
    , m_zoom(DEFAULT_ZOOM)
    , m_progress(0)
    , m_loading(false)
    , m_width(0)
    , m_height(0)
{
}

WebView::~WebView()
{
    if (m_view)
        macross_view_destroy(m_view);
    if (m_canvas)
        lv_obj_delete(m_canvas);
}

void WebView::create(int x, int y, int w, int h)
{
    m_width = w;
    m_height = h;

    /* Create LVGL canvas for rendering */
    m_canvas = lv_canvas_create(m_parent);
    lv_obj_set_pos(m_canvas, x, y);
    lv_obj_set_size(m_canvas, w, h);

    static lv_color_t* buf = (lv_color_t*)lv_malloc(w * h * sizeof(lv_color_t));
    lv_canvas_set_buffer(m_canvas, buf, w, h, LV_COLOR_FORMAT_NATIVE);
    lv_canvas_fill_bg(m_canvas, lv_color_white(), LV_OPA_COVER);

    /* Create Agave engine view */
    unsigned char* pixels = (unsigned char*)buf;
    m_view = macross_view_create(pixels, w, h, w * sizeof(lv_color_t), 0);

    /* Set callbacks */
    macross_view_set_update_callback(m_view, on_update, this);
    macross_view_set_loading_callback(m_view, on_loading, this);
    macross_view_set_title_callback(m_view, on_title, this);
    macross_view_set_url_callback(m_view, on_url, this);
    macross_view_set_error_callback(m_view, on_error, this);

    /* Enable touch events on canvas */
    lv_obj_add_flag(m_canvas, LV_OBJ_FLAG_CLICKABLE);
    lv_obj_add_event_cb(m_canvas, canvas_draw_cb, LV_EVENT_DRAW_MAIN, this);
}

void WebView::loadUrl(const char* url)
{
    if (m_view)
        macross_view_load_url(m_view, url);
}

void WebView::goBack()
{
    if (m_view)
        macross_view_go_back(m_view);
}

void WebView::goForward()
{
    if (m_view)
        macross_view_go_forward(m_view);
}

void WebView::reload()
{
    if (m_view)
        macross_view_reload(m_view);
}

void WebView::stop()
{
    if (m_view)
        macross_view_stop_load(m_view);
}

void WebView::scrollBy(int dx, int dy)
{
    if (m_view)
        macross_view_set_scroll_position(m_view, scrollX() + dx, scrollY() + dy);
}

void WebView::setZoom(float factor)
{
    if (factor < MIN_ZOOM) factor = MIN_ZOOM;
    if (factor > MAX_ZOOM) factor = MAX_ZOOM;
    m_zoom = factor;
    if (m_view)
        macross_view_set_zoom(m_view, factor);
}

int WebView::contentsWidth() const
{
    MC_SIZE size = {0, 0};
    if (m_view)
        macross_view_get_contents_size(m_view, &size);
    return size.w;
}

int WebView::contentsHeight() const
{
    MC_SIZE size = {0, 0};
    if (m_view)
        macross_view_get_contents_size(m_view, &size);
    return size.h;
}

int WebView::scrollX() const
{
    MC_POINT pos = {0, 0};
    if (m_view)
        macross_view_get_scroll_position(m_view, &pos);
    return pos.x;
}

int WebView::scrollY() const
{
    MC_POINT pos = {0, 0};
    if (m_view)
        macross_view_get_scroll_position(m_view, &pos);
    return pos.y;
}

void WebView::handleTouch(int x, int y, int type)
{
    if (!m_view) return;

    MC_MOUSE_EVENT evt;
    evt.x = x;
    evt.y = y;
    evt.button = 1;

    switch (type) {
    case LV_EVENT_PRESSED:
        macross_view_mouse_event(m_view, &evt, MC_MOUSE_PRESS);
        break;
    case LV_EVENT_RELEASED:
        macross_view_mouse_event(m_view, &evt, MC_MOUSE_RELEASE);
        break;
    case LV_EVENT_PRESSING:
        macross_view_mouse_event(m_view, &evt, MC_MOUSE_MOVE);
        break;
    }
}

void WebView::repaint()
{
    if (m_canvas)
        lv_obj_invalidate(m_canvas);
}

/* Callbacks */
void WebView::on_update(MaCrossView* view, const MC_RECT* rect, void* data)
{
    WebView* self = (WebView*)data;
    self->repaint();
}

void WebView::on_loading(MaCrossView* view, unsigned int progress, MC_BOOL finish, void* data)
{
    WebView* self = (WebView*)data;
    self->m_progress = progress;
    self->m_loading = !finish;
}

void WebView::on_title(MaCrossView* view, const char* title, void* data)
{
    (void)view; (void)title; (void)data;
}

void WebView::on_url(MaCrossView* view, const char* url, void* data)
{
    (void)view; (void)url; (void)data;
}

void WebView::on_error(MaCrossView* view, MC_STATUS status, const char* url, void* data)
{
    (void)view; (void)status; (void)url; (void)data;
}

void WebView::canvas_draw_cb(lv_event_t* e)
{
    (void)e;
    /* Canvas buffer is directly written by Agave engine, just invalidate */
}

