void MainWindow::createProgressBar()
{
    /* Arc progress indicator around the edge */
    m_progress = lv_arc_create(m_bg);
    lv_obj_set_size(m_progress, SCREEN_WIDTH - 8, SCREEN_HEIGHT - 8);
    lv_obj_center(m_progress);
