    lv_obj_center(lbl_fwd);
    lv_obj_add_event_cb(m_btn_forward, on_forward_click, LV_EVENT_CLICKED, this);
}

void MainWindow::loadUrl(const char* url)
{
    if (m_webview)
        m_webview->loadUrl(url);
    if (m_addr_bar)
        lv_textarea_set_text(m_addr_bar, url);
}

/* Event handlers */
void MainWindow::on_addr_submit(lv_event_t* e)
{
    MainWindow* self = (MainWindow*)lv_event_get_user_data(e);
    const char* text = lv_textarea_get_text(self->m_addr_bar);
    if (text && text[0])
        self->m_webview->loadUrl(text);
}

void MainWindow::on_back_click(lv_event_t* e)
{
    MainWindow* self = (MainWindow*)lv_event_get_user_data(e);
    self->m_webview->goBack();
