void MainWindow::on_forward_click(lv_event_t* e)
{
    MainWindow* self = (MainWindow*)lv_event_get_user_data(e);
    self->m_webview->goForward();
}

void MainWindow::on_reload_click(lv_event_t* e)
{
    MainWindow* self = (MainWindow*)lv_event_get_user_data(e);
    self->m_webview->reload();
}

