/* app.cpp - WatchWeb application
 *
 * Copyright (C) 2026 Zhang Ji Peng
 * Contact : onecoolx@gmail.com
 */

#include "config.h"

#define SDL_MAIN_HANDLED
#include "lvgl.h"
#include "macross.h"

#include "app.h"
#include "mainwindow.h"

App* App::s_instance = nullptr;

App::App()
    : m_window(nullptr)
    , m_display(nullptr)
    , m_engine_timer(nullptr)
    , m_running(false)
{
    s_instance = this;
}

App::~App()
{
    delete m_window;
    macross_shutdown();
    lv_deinit();
    s_instance = nullptr;
}

App* App::instance()
{
    if (!s_instance)
        s_instance = new App();
    return s_instance;
}

bool App::init(int argc, char** argv)
{
    /* Initialize LVGL */
    lv_init();

    /* Create SDL display (480x480 for circular watch) */
    m_display = lv_sdl_window_create(SCREEN_WIDTH, SCREEN_HEIGHT);
    if (!m_display)
        return false;

    /* Create SDL input devices */
    lv_sdl_mouse_create();
    lv_sdl_mousewheel_create();
    lv_sdl_keyboard_create();

    /* Initialize Agave engine */
    macross_initialize(SCREEN_WIDTH, SCREEN_HEIGHT, 0);

    /* Create main window */
    m_window = new MainWindow();
    m_window->create();

    /* Load initial URL */
    if (argc > 1)
        m_window->loadUrl(argv[1]);
    else
        m_window->loadUrl("about:blank");

    /* Engine event dispatch timer (16ms ≈ 60fps) */
    m_engine_timer = lv_timer_create(engine_dispatch_cb, 16, nullptr);

    m_running = true;
    return true;
}

int App::run()
{
    while (m_running) {
        uint32_t delay = lv_timer_handler();
        lv_delay_ms(delay < 5 ? 5 : delay);
    }
    return 0;
}

void App::quit()
{
    m_running = false;
}

void App::engine_dispatch_cb(lv_timer_t* timer)
{
    (void)timer;
    macross_event_dispatch();
}

