static void offsets_combine_rects(const Rect& from, const Rect& to, int* x, int* y)
{
    if (to.x < from.x) {
        *x += to.x - from.x;
    } else if ((to.x + to.w) > (from.x + from.w)) {
        *x += (to.x + to.w) - (from.x + from.w);
    } else {
        *x += 0;
    }

    if (to.y < from.y) {
        *y += to.y - from.y;
    } else if ((to.y + to.h) > (from.y + from.h)) {
        *y += (to.y + to.h) - (from.y + from.h);
    } else {
        *y += 0;
    }
}

