#ifndef _WATCHWEB_WEBVIEW_H_
#define _WATCHWEB_WEBVIEW_H_

#include "config.h"
#include "macross.h"

class WebView {
public:
    WebView();
    ~WebView();

    void create(int view_w, int view_h);
    void destroy();

    /* Navigation */
    void loadUrl(const char* url);
    void goBack();
    void goForward();
    void reload();
    void stop();

    /* Scroll (pixel delta) */
    void scrollBy(int dx, int dy);
    void scrollTo(int x, int y);
    int scrollX() const { return m_pos_x; }
    int scrollY() const { return m_pos_y; }

    /* Zoom */
    void setZoom(float factor);
    float zoom() const { return m_zoom; }

    /* Content info */
    int contentsWidth() const;
    int contentsHeight() const;

    /* State */
    bool isLoading() const { return m_loading; }
    unsigned int progress() const { return m_progress; }
    const char* title() const { return m_title; }
    const char* url() const { return m_url; }

    /* Get visible pixels (for blitting to LVGL canvas) */
    const uint8_t* visibleBuffer() const;
    int visibleOffsetX() const;
    int visibleOffsetY() const;
    int bufferPitch() const { return TILE_BUF_W * 4; }

    /* Touch input forwarding */
    void mousePress(int x, int y);
    void mouseMove(int x, int y);
    void mouseRelease(int x, int y);

    /* Callbacks (set by UI layer) */
    typedef void (*UpdateCb)(void* ctx);
    typedef void (*StateCb)(void* ctx);
    void setUpdateCallback(UpdateCb cb, void* ctx) { m_update_cb = cb; m_update_ctx = ctx; }
    void setStateCallback(StateCb cb, void* ctx) { m_state_cb = cb; m_state_ctx = ctx; }

private:
    void updateTileOffset();

    /* Agave callbacks */
    static void on_dirty(MaCrossView* v, const MC_RECT* r);
    static void on_update(MaCrossView* v);
    static void on_loading(MaCrossView* v, unsigned int prog, MC_BOOL finish);
    static void on_title(MaCrossView* v, const char* title);
    static void on_url(MaCrossView* v, const char* url);

    MaCrossView* m_view;
    uint8_t* m_buffer;      /* tile buffer (TILE_BUF_W x TILE_BUF_H) */
    int m_view_w, m_view_h; /* visible viewport size */
    int m_pos_x, m_pos_y;   /* scroll position in content coords */
    int m_off_x, m_off_y;   /* tile buffer offset (where viewport maps into buffer) */
    float m_zoom;
    bool m_loading;
    unsigned int m_progress;
    char m_title[256];
    char m_url[1024];

    UpdateCb m_update_cb;
    void* m_update_ctx;
    StateCb m_state_cb;
    void* m_state_ctx;
};

#endif /* _WATCHWEB_WEBVIEW_H_ */

