target_link_libraries(${APP_WATCH} PRIVATE
                                    lvgl
                                    ${SDL2_LIBRARIES}
                                    ${LIB_NAME}
                                    picasso2_sw
                                    ${SYSTEM_LIBS} 
                                    ${CMAKE_DL_LIBS} 
)

