void WebView::loadUrl(const char* url) { if (m_view) macross_view_open_url(m_view, url); }
void WebView::goBack() { if (m_view) macross_view_backward(m_view); }
void WebView::goForward() { if (m_view) macross_view_forward(m_view); }
