bool running = true;
while (running) {
    /* Check for quit before LVGL consumes the event */
    if (SDL_QuitRequested()) {
        running = false;
        break;
    }

    macross_event_dispatch();

    if (g_dirty) {
        g_dirty = false;
        macross_view_update(g_webview->view(), NULL);
        g_ui->updateCanvas();
