void WatchUI::on_canvas_move(lv_event_t* e)
{
    WatchUI* ui = (WatchUI*)lv_event_get_user_data(e);
    lv_point_t p;
    lv_indev_get_point(lv_indev_active(), &p);
    int dx = ui->m_tx - p.x;
    int dy = ui->m_ty - p.y;

    if (!ui->m_dragging && (abs(dx) > 5 || abs(dy) > 5)) {
        ui->m_dragging = true;
    }

    if (ui->m_dragging) {
        ui->m_wv->scrollBy(dx, dy);
        ui->m_tx = p.x;
        ui->m_ty = p.y;
        ui->updateCanvas();
    }
}

