#define TILE_BUF_H      (CONTENT_HEIGHT * 3)

/* UI metrics */
#define NAV_BTN_SIZE    56
#define PROGRESS_WIDTH  4
/* Floating toggle icon at bottom-center */
#define FAB_SIZE        40
#define FAB_MARGIN      8
/* Bottom navigation panel (slides up from bottom) */
#define NAV_BAR_H       88

