/* The engine's virtual screen must match the layout viewport (LAYOUT_WIDTH),
   not the 480px physical panel: screenRect drives CSS media queries and
   screen.width, so a desktop-like width keeps responsive sites on their
   desktop layout (consistent with minimum_layout_size). The physical LVGL
   window stays 480; page-zoom shrinks the rendered result to fit. */
int screen_h = (int)(LAYOUT_WIDTH * (float)SCREEN_HEIGHT / (float)SCREEN_WIDTH);
if (macross_initialize(PIXEL_FORMAT_BGRA32, LAYOUT_WIDTH, screen_h) != MC_STATUS_SUCCESS) {
    fprintf(stderr, "Failed to initialize Agave engine\n");
    return -1;
}

