    if(disp_refr == NULL) {
        LV_LOG_WARN("No display registered");
        return;
    }

    lv_draw_buf_t * buf_act = disp_refr->buf_act;
    if(!(buf_act && buf_act->data && buf_act->data_size)) {
        LV_LOG_WARN("No draw buffer");
        return;
    }

    lv_display_send_event(disp_refr, LV_EVENT_REFR_START, NULL);

